#include <iostream>
using namespace std;

bool isPrime(int x) {
    for (int i = 2; i * i <= x; i++)
        if (x % i == 0) return false;
    return true;
}

int main() {
    int a[9] = {0, 1, 2, 3, 4, 5, -7, 9, 11};
    int dem = 0;
    for (int i = 0; i < 9; i++)
        if (isPrime(a[i])) dem++;
    cout << dem << endl;
    return 0;
}

#include <iostream>
using namespace std;

bool isPerfect(int x) {
    int s = 0;
    for (int i = 1; i <= x / 2; i++)
        if (x % i == 0) s += i;
    return s == x;
}

int main() {
    int a[7] = {6, 28, 12, 496, 1, 0, 8128};
    int dem = 0;
    for (int i = 0; i < 7; i++)
        if (isPerfect(a[i])) dem++;
    cout << dem << endl;
    return 0;
}

