    for (int i = 0; i < n; i++)
        if (isPrime(a[i])) return i;
    return -1;
}

int firstPrime(int a[], int n) {
    for (int i = n - 1; i >= 0; i--)
        if (isPrime(a[i])) return a[i];
    return -1;
}

