}

#include <iostream>
using namespace std;

int ucln(int a, int b) {
    while (b != 0) { int r = a % b; a = b; b = r; }
    return a;
}

int main() {
    int a[4] = {48, 18, 27, 9};
    int g = a[0];
    cout << g;
    for (int i = 1; i < 4; i++) {
        g = ucln(g, a[i]);
        cout << ' ' << g;
    }
    cout << endl;
    return 0;
}

