#include <iostream>
using namespace std;

bool palin(int x) {
    int t = x, r = 0;
    while (t > 0) { r = r * 10 + t % 10; t /= 10; }
    return r == x;
}

int main() {
    int a[4] = {-33, 10, 0, 121};
    int kq = -1;
    for (int i = 0; i < 4; i++)
        if (palin(a[i])) { kq = a[i]; break; }
    cout << kq << endl;
    return 0;
}

